CFDLean.Assembly.Interfaces.reindex.eq_1.type:
∀ {N : Type u_1} {E : Type u_2} {B : Type u_3} {N' : Type u_4} {E' : Type u_5} {B' : Type u_6}
  (m : CFDLean.Assembly.Interfaces N E B) (n : N ≃ N') (e : E ≃ E') (b : B ≃ B'),
  m.reindex n e b =
    { tail := fun j => n (m.tail (e.symm j)), head := fun j => n (m.head (e.symm j)), distinct := ⋯,
      owner := fun j => n (m.owner (b.symm j)) }

CFDLean.Assembly.global_balance.type:
∀ {N : Type u_1} {E : Type u_2} {B : Type u_3} [inst : DecidableEq N] [inst_1 : Fintype E] [inst_2 : Fintype B] {d : ℕ}
  [inst_3 : Fintype N] (m : CFDLean.Assembly.Interfaces N E B) (f : E → CFDLean.Vector d) (g : B → CFDLean.Vector d),
  ∑ i, CFDLean.Assembly.residual m f g i = ∑ b, g b

